 */
export function cropAndScale(y, width, height, opts = {}) {
  const rotation = opts.rotation ?? 0;
  const crop = opts.cropFraction ?? CROP_FRACTION;
  const maxSide = opts.maxSide ?? MAX_SIDE;
  const cw = Math.max(1, Math.round(width * crop));
  const ch = Math.max(1, Math.round(height * crop));
  const x0 = Math.floor((width - cw) / 2);
  const y0 = Math.floor((height - ch) / 2);
  const scale = Math.min(1, maxSide / Math.max(cw, ch));
  const sw = Math.max(1, Math.round(cw * scale));
  const sh = Math.max(1, Math.round(ch * scale));

  // Box filter: each output pixel averages the source pixels that fall inside it.
  const scaled = new Uint8Array(sw * sh);
  for (let oy = 0; oy < sh; oy++) {
    const sy0 = y0 + Math.floor((oy * ch) / sh);
    const sy1 = Math.max(sy0 + 1, y0 + Math.floor(((oy + 1) * ch) / sh));
    for (let ox = 0; ox < sw; ox++) {
      const sx0 = x0 + Math.floor((ox * cw) / sw);
      const sx1 = Math.max(sx0 + 1, x0 + Math.floor(((ox + 1) * cw) / sw));
      let sum = 0;
      for (let sy = sy0; sy < sy1; sy++) {
        const row = sy * width;
        for (let sx = sx0; sx < sx1; sx++) sum += y[row + sx];
      }
      scaled[oy * sw + ox] = Math.round(sum / ((sy1 - sy0) * (sx1 - sx0)));
    }
  }
  return rotate(scaled, sw, sh, rotation);
}

/** Rotates a grayscale image clockwise by 0, 90, 180 or 270 degrees. */
export function rotate(data, width, height, rotation) {
  if (rotation === 0) return { data, width, height };
  const out = new Uint8Array(data.length);
  const w2 = rotation === 180 ? width : height;
  const h2 = rotation === 180 ? height : width;
  for (let yy = 0; yy < height; yy++) {
    for (let xx = 0; xx < width; xx++) {
      let nx, ny;
      if (rotation === 90) { nx = height - 1 - yy; ny = xx; }
      else if (rotation === 180) { nx = width - 1 - xx; ny = height - 1 - yy; }
      else { nx = yy; ny = width - 1 - xx; }
      out[ny * w2 + nx] = data[yy * width + xx];
    }
  }
  return { data: out, width: w2, height: h2 };
}

/**
 * Exposure statistics of a grayscale image: mean luma, and the share of clipped highlights (glare)
 * and near-black pixels. Thresholds were chosen from the Stage C probe (lens covered: luma 12-20).
 */
export function quality(data) {
  let sum = 0, bright = 0, black = 0;
  for (let i = 0; i < data.length; i++) {
    const v = data[i];
    sum += v;
    if (v >= 250) bright++;
    if (v <= 24) black++;
  }
  const n = Math.max(1, data.length);
  const mean = sum / n;
  return {
    luma: Math.round(mean * 10) / 10,
    clipped: Math.round((bright / n) * 1000) / 1000,
    glare: bright / n >= 0.06,
    dark: mean < 30 && black / n > 0.5,
  };
}

/** Encodes an 8-bit grayscale image as PNG (in memory). */
export function encodeGrayPng(data, width, height) {
  const raw = Buffer.alloc((width + 1) * height);
  for (let yy = 0; yy < height; yy++) {
    raw[yy * (width + 1)] = 0; // filter: none
    raw.set(data.subarray(yy * width, (yy + 1) * width), yy * (width + 1) + 1);
  }
  const chunk = (type, body) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(body.length);
    const tb = Buffer.concat([Buffer.from(type, 'ascii'), body]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(tb) >>> 0);
    return Buffer.concat([len, tb, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 0; // colour type: grayscale
  ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 6 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

// One vision request to the Gemini API (generateContent, free tier, GOOGLE_API_KEY): image in,
// card fields out as JSON constrained by CARD_SCHEMA. The key is sent only in the x-goog-api-key
// header and is never logged.
import { CARD_SCHEMA, VISION_PROMPT } from './card-reader.mjs';

// Confirmed 2026-11-14 in Google's model docs: stable, image input, structured output, and "minimal"
// thinking for low latency. Listed by GET /v1beta/models for this key. Override with VISION_MODEL.
export const DEFAULT_VISION_MODEL = 'gemini-3.5-flash-lite';
const API = 'https://generativelanguage.googleapis.com/v1beta/models';

export class VisionError extends Error {
  /** @param {string} code @param {string} message @param {number | null} [retryAfterMs] */
  constructor(code, message, retryAfterMs = null) {
    super(message);
    this.code = code;
    this.retryAfterMs = retryAfterMs;
  }
}

/** Reads "retryDelay": "12s" from a Gemini 429 error body, if present. */
function retryDelayMs(body) {
  const d = body?.error?.details?.find(x => typeof x?.retryDelay === 'string')?.retryDelay;
  const m = typeof d === 'string' ? /^([\d.]+)s$/.exec(d) : null;
  return m ? Math.ceil(Number(m[1]) * 1000) : null;
}

/**
 * @param {Buffer} png grayscale PNG bytes (in memory only)
 * @param {{ model?: string, apiKey?: string, timeoutMs?: number, thinkingLevel?: string | null }} [opts]
 * @returns {Promise<string>} the model's raw JSON text (parse it with parseCardReading)
 */
export async function readCardImage(png, opts = {}) {
  const model = opts.model || process.env.VISION_MODEL || DEFAULT_VISION_MODEL;
  const apiKey = opts.apiKey ?? process.env.GOOGLE_API_KEY;
  if (!apiKey) throw new VisionError('no_key', 'GOOGLE_API_KEY is not set');
  const thinkingLevel = opts.thinkingLevel === undefined ? (process.env.VISION_THINKING ?? 'minimal') : opts.thinkingLevel;
  const generationConfig = {
    temperature: 0,
    responseMimeType: 'application/json',
    responseJsonSchema: CARD_SCHEMA,
    ...(thinkingLevel ? { thinkingConfig: { thinkingLevel } } : {}),
  };
  let res;
  try {
    res = await fetch(`${API}/${encodeURIComponent(model)}:generateContent`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-goog-api-key': apiKey },
      body: JSON.stringify({
        contents: [{
          role: 'user',
          parts: [
            { text: VISION_PROMPT },
            { inlineData: { mimeType: 'image/png', data: png.toString('base64') } },
          ],
        }],
        generationConfig,
      }),
      signal: AbortSignal.timeout(opts.timeoutMs ?? 10_000),
    });
  } catch (e) {
    const name = /** @type {any} */ (e)?.name;
    throw new VisionError(name === 'TimeoutError' ? 'timeout' : 'network', String(/** @type {any} */ (e)?.message ?? e));
  }
  const body = await res.json().catch(() => null);
  if (!res.ok) {
    const msg = String(body?.error?.message ?? res.statusText).slice(0, 300);
    if (res.status === 429) throw new VisionError('rate_limited', msg, retryDelayMs(body));
    throw new VisionError(`http_${res.status}`, msg);
  }
  const candidate = body?.candidates?.[0];
  const text = candidate?.content?.parts?.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join('') ?? '';
  if (!text) throw new VisionError('empty', `no text (finishReason=${candidate?.finishReason ?? 'none'}, block=${body?.promptFeedback?.blockReason ?? 'none'})`);
  return text;
}

