import { readFileSync } from 'node:fs';
const A = process.env.AGENT_DIR;
const { cropAndScale, encodeGrayPng, quality } = await import(A + '/frame-utils.mjs');
const { readCardImage } = await import(A + '/vision.mjs');
const { parseCardReading } = await import(A + '/card-reader.mjs');
function bmpLuma(path) {
  const b = readFileSync(path);
  const off = b.readUInt32LE(10), w = b.readInt32LE(18), hRaw = b.readInt32LE(22), bpp = b.readUInt16LE(28);
  const h = Math.abs(hRaw), bytes = bpp / 8, stride = Math.ceil((w * bytes) / 4) * 4;
  const y = new Uint8Array(w * h);
  for (let r = 0; r < h; r++) {
    const src = off + (hRaw > 0 ? h - 1 - r : r) * stride;
    for (let x = 0; x < w; x++) {
      const i = src + x * bytes, B = b[i], G = b[i + 1], R = b[i + 2];
      y[r * w + x] = Math.round(16 + 0.257 * R + 0.504 * G + 0.098 * B); // BT.601 studio range, like I420
    }
  }
